<?php $this->load->view('admin/feeworkspace/_header'); $months=array(1=>'January',2=>'February',3=>'March',4=>'April',5=>'May',6=>'June',7=>'July',8=>'August',9=>'September',10=>'October',11=>'November',12=>'December'); ?>
<div class="fw-card"><div class="fw-card-head"><h3><i class="fa fa-file-text-o"></i> Generate challan</h3></div><div class="fw-card-body">
<div class="fw-tabs"><a href="#" class="active fw-challan-mode" data-mode="student"><i class="fa fa-user"></i> Student challan</a><a href="#" class="fw-challan-mode" data-mode="family"><i class="fa fa-users"></i> Family challan</a></div>
<form id="fw-challan-form" class="fw-process-form" action="<?php echo site_url('challanform/generateChallanForm'); ?>" method="post" target="_blank"><?php echo $this->customlib->getCSRF(); ?><input type="hidden" name="search" value="search_filter">
<div class="row"><div class="col-sm-3 form-group"><label class="fw-label">Year *</label><select class="form-control" name="year" required><?php for($y=date('Y')-3;$y<=date('Y')+2;$y++){ ?><option <?php echo $y==date('Y')?'selected':''; ?>><?php echo $y; ?></option><?php } ?></select></div><div class="col-sm-3 form-group"><label class="fw-label">Month *</label><select class="form-control" name="month" required><?php foreach($months as $n=>$m){ ?><option value="<?php echo $n; ?>" <?php echo $n==date('n')?'selected':''; ?>><?php echo $m; ?></option><?php } ?></select></div><div class="col-sm-3 form-group"><label class="fw-label">Class <span class="fw-student-required">*</span></label><select class="form-control" id="fw-ch-class" name="class_id"><option value="">All classes</option><?php foreach($classlist as $c){ ?><option value="<?php echo (int)$c['id']; ?>"><?php echo html_escape($c['class']); ?></option><?php } ?></select></div><div class="col-sm-3 form-group"><label class="fw-label">Section <span class="fw-student-required">*</span></label><select class="form-control" id="fw-ch-section" name="section_id"><option value="">All sections</option></select></div></div>
<div class="row"><div class="col-sm-9 form-group fw-student-only"><label class="fw-label">Student *</label><select class="form-control" id="fw-ch-student" name="student"><option value="">Select class and section first</option></select></div><div class="col-sm-3"><label class="fw-label">&nbsp;</label><button type="submit" class="fw-btn fw-btn-success btn-block"><i class="fa fa-print"></i> Generate & Open PDF</button></div></div>
</form><div class="fw-note"><i class="fa fa-info-circle"></i> Student mode can generate one student or the whole selected class/section. Family mode creates the existing sibling challan format.</div></div></div>
<script>(function($){var form=$('#fw-challan-form');$('.fw-challan-mode').on('click',function(e){e.preventDefault();$('.fw-challan-mode').removeClass('active');$(this).addClass('active');var family=$(this).data('mode')==='family';form.attr('action',family?'<?php echo site_url('FamilyChallanform/generateChallanForm'); ?>':'<?php echo site_url('challanform/generateChallanForm'); ?>');$('.fw-student-only,.fw-student-required').toggle(!family);$('#fw-ch-class,#fw-ch-section,#fw-ch-student').prop('required',!family);});$('#fw-ch-class').on('change',function(){var s=$('#fw-ch-section').html('<option value="">Select section</option>'),id=this.value;$('#fw-ch-student').html('<option value="">Select class and section first</option>');if(!id)return;$.getJSON('<?php echo site_url('sections/getByClass'); ?>',{class_id:id},function(a){$.each(a,function(_,x){s.append($('<option>').val(x.section_id||x.id).text(x.section));});});});$('#fw-ch-section').on('change',function(){var s=$('#fw-ch-student').html('<option>Loading...</option>');$.getJSON('<?php echo site_url('challanform/getStudents'); ?>',{CLASS_ID:$('#fw-ch-class').val(),SECTION_ID:this.value},function(a){s.html('<option value="ALL">ALL STUDENTS</option>');$.each(a,function(_,x){s.append($('<option>').val(x.id).text(x.student_name+' ('+x.admission_no+')'));});});});form.on('submit',function(){var b=$(this).find('[type=submit]');setTimeout(function(){form.data('busy',0).removeClass('fw-processing');b.prop('disabled',false).html('<i class="fa fa-print"></i> Generate & Open PDF');},1500);});})(jQuery);</script>
